def run_test(candidate_fn):
    try:
        cb = candidate_fn(3)
    except TypeError:
        raise AssertionError('CircularBuffer must accept size as argument')
    assert cb.read() == [], f'Expected [], got {cb.read()}'
    cb.append(1); cb.append(2); cb.append(3)
    assert cb.read() == [1, 2, 3], f'Expected [1,2,3], got {cb.read()}'
    cb.append(4)
    assert cb.read() == [2, 3, 4], f'Expected [2,3,4], got {cb.read()}'

def run_test(candidate_fn):
    g1 = {'a':['b'],'b':['c'],'c':[]}
    r1 = candidate_fn(g1)
    assert r1.index('a') < r1.index('b') < r1.index('c'), f'Got {r1}'
    g2 = {'a':['b','c'],'b':['d'],'c':['d'],'d':[]}
    r2 = candidate_fn(g2)
    assert r2.index('a') < r2.index('d'), f'Got {r2}'
    assert r2.index('b') < r2.index('d'), f'Got {r2}'
    r3 = candidate_fn({'x':[]})
    assert r3 == ['x'], f'Got {r3}'

